package com.damidu.supermariodsa.lwjgl3;

import org.lwjgl.system.macosx.LibC;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.lang.management.ManagementFactory;
import java.util.ArrayList;
import java.util.List;

/**
 * Ensures macOS JVM starts on the first thread for LWJGL3 / GLFW compatibility.
 * Standard utility generated by GDX-Liftoff for desktop platforms.
 */
public class StartupHelper {

    private static final String JVM_RESTARTED_KEY = "jvm.restarted";

    private StartupHelper() {
        // Prevent instantiation
    }

    public static boolean startNewJvmIfRequired() {
        String osName = System.getProperty("os.name").toLowerCase();
        if (!osName.contains("mac")) {
            return false;
        }

        // If already restarted or running on first thread, do nothing
        if ("true".equals(System.getProperty(JVM_RESTARTED_KEY))) {
            return false;
        }

        List<String> jvmArgs = ManagementFactory.getRuntimeMXBean().getInputArguments();
        boolean hasStartOnFirstThread = false;
        for (String jvmArg : jvmArgs) {
            if (jvmArg.contains("-XstartOnFirstThread")) {
                hasStartOnFirstThread = true;
                break;
            }
        }

        if (hasStartOnFirstThread) {
            return false;
        }

        // Restart JVM with -XstartOnFirstThread
        String javaHome = System.getProperty("java.home");
        String javaBin = javaHome + "/bin/java";
        List<String> command = new ArrayList<>();
        command.add(javaBin);
        command.add("-XstartOnFirstThread");
        command.add("-D" + JVM_RESTARTED_KEY + "=true");
        command.addAll(jvmArgs);
        command.add("-cp");
        command.add(System.getProperty("java.class.path"));
        command.add(System.getProperty("sun.java.command"));

        try {
            Process process = new ProcessBuilder(command).inheritIO().start();
            process.waitFor();
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
